  ctx=[ex("En un juego de mesa, una pieza está en (−4, 2) y una carta dice «avanza (6, −3)». ¿En qué casilla queda la pieza?", "(2, −1)", "(−4 + 6, 2 + (−3)) = (2, −1).")],
